inline flight::types::CommandBindingTable create_command_binding_table() {
  return flight::Map<flight::String, flight::Ref<flight::types::CommandBinding>>();
}

inline std::optional<flight::Ref<flight::types::CommandBinding>> get_command_binding(flight::StructuralRef<flight::RowReadonly<flight::RowOf<flight::Ref<flight::types::CommandHistory>>>> history, flight::String kind) {
  return flight::row_get<flight::RowKey<"bindings">>(history).get(kind);
}

inline bool has_command_binding(flight::StructuralRef<flight::RowReadonly<flight::RowOf<flight::Ref<flight::types::CommandHistory>>>> history, flight::String kind) {
  return get_command_binding(history, kind).has_value();
}

inline void initialize_set_node_property_command(flight::types::EntityConstruction<flight::Ref<flight::types::SetNodePropertyCommand>> out, flight::Array<flight::Ref<flight::types::CommandPropertyEntry>> entries, flight::String kind, flight::String label, double merge_window, double time) {
  flight::row_set<flight::RowKey<"entries">>(out, entries);
  flight::row_set<flight::RowKey<"kind">>(out, kind);
  flight::row_set<flight::RowKey<"label">>(out, label);
  flight::row_set<flight::RowKey<"mergeWindow">>(out, merge_window);
  flight::row_set<flight::RowKey<"time">>(out, time);
}

inline void register_command_binding(flight::Ref<flight::types::CommandHistory> history, flight::String kind, flight::Ref<flight::types::CommandBinding> binding) {
  (history->bindings = flight::registry::with_kind_map_entry<flight::Ref<flight::types::CommandBinding>>(history->bindings, kind, binding));
}


